INSERT INTO `v1_4d12808c6a37d7aae9306e039a18ca0d342400a41ec7b631222937b03290c7ee` VALUES (906802, 10201, 1020101, 1020101, "ようこそ我ら七冠の開発室へ。ここにはアタシたちがレジェンドオブ\nアストルムを開発していた時の記録が残されているらしい。当時の\n極秘データも見れちゃったりするけど、口外禁止で頼むよ、少年。");
INSERT INTO `v1_4d12808c6a37d7aae9306e039a18ca0d342400a41ec7b631222937b03290c7ee` VALUES (105901, 10213, 1021301, 1021301, "裏世界のプリンセスのみなさまが、きたる『ビストロプリンセス』に備え\nお料理の練習に励まれるようです。『福弾けさせりゃ、一人前』……。\nいったい、どのような反応を意味するお言葉なのでしょうか。");
INSERT INTO `v1_4d12808c6a37d7aae9306e039a18ca0d342400a41ec7b631222937b03290c7ee` VALUES (105901, 10213, 1021302, 1021302, "『出張ビストロ』オープンの噂は瞬く間に広まり、早くも来訪のご予約が\n殺到しているのだとか。これも、お三方が持つ『カリスマ性』によるもの\nでございますね。主さまもみなさまのお手伝い、頑張ってくださいまし。");
